fmi3Status fmi3GetFloat64(fmi3Instance instance, const fmi3ValueReference vr[], size_t nvr, fmi3Float64 values[], size_t nValues) {
    FMUModelData *modelData = (FMUModelData *)instance;
    _instance = modelData;
    size_t i;
    int counter = 0;
    if (nvr != 0 && (!values || !vr)) {
        if(modelData->loggingOn && modelData->logMessage)
            modelData->logMessage(modelData->instanceEnvironment, fmi3Error, "error", "invalid memory access in fmi3GetFloat64");
        return fmi3Error;
    }
    for (i = 0; i < nvr; i++) {
        if (vr[i] >= 36 || vr[i] < 0) {
            if(modelData->loggingOn && modelData->logMessage)
                modelData->logMessage(modelData->instanceEnvironment, fmi3Error, "error", "valueReference out of range in fmi3GetFloat64");
            return fmi3Error;
        }
    }
    for (i = 0; i < nvr; i++) {
       size_t idx = vr[i]-0;
        updateArrayData(modelData->idxVector, modelData->inDim, modelData->rList[idx],  modelData->rListSize[idx], modelData->rListDims[idx], (void*)(values+counter), true, sizeof(fmi3Float64));
        counter += modelData->rListSize[idx];
    }
    if ( counter != nValues ) {
        if(modelData->loggingOn && modelData->logMessage)
            modelData->logMessage(modelData->instanceEnvironment, fmi3Error, "error", "incorrect num of nv in fmi3GetFloat64");
        return fmi3Error;
    }
    printLogMsg(instance, vr, nvr, "getFloat64", values, 0, modelData->rListSize);
    return fmi3OK;
}

