fmi3Status fmi3GetFMUState(fmi3Instance instance, fmi3FMUState* FMUState) {
    FMUModelData *modelData = (FMUModelData *)instance;
    _instance = modelData;
    FMUInternalState* fmuInternalState = (FMUInternalState*)calloc(1, sizeof(FMUInternalState));
    memcpy(&fmuInternalState->ExternalInput, &multibody_model_U, sizeof(ExtU_multibody_model_T));
    memcpy(&fmuInternalState->ExternalOutput, &multibody_model_Y, sizeof(ExtY_multibody_model_T));
    memcpy(&fmuInternalState->Parameter, &multibody_model_P, sizeof(P_multibody_model_T));
    memcpy(&fmuInternalState->RTModel, modelData->S, sizeof(RT_MODEL_multibody_model_T));
    memcpy(&fmuInternalState->blockBuffer, &multibody_model_B, sizeof(B_multibody_model_T));
    memcpy(&fmuInternalState->dWork, &multibody_model_DW, sizeof(DW_multibody_model_T));
    size_t i;
    for(i = 0; i < 36; i++) {
       fmuInternalState->float64ListBuffer[i] = *modelData->rList[i];
    }
    if (multibody_model_DW.Model1_InstanceData.rtdw.STATE_1_Simulator) {
        fmuInternalState->ssOp[0] = nesl_save_simdata(multibody_model_DW.Model1_InstanceData.rtdw.STATE_1_Simulator, &fmuInternalState->ssStateSize[0]);
    }
    if (multibody_model_DW.Model1_InstanceData.rtdw.OUTPUT_1_0_Simulator) {
        fmuInternalState->ssOp[1] = nesl_save_simdata(multibody_model_DW.Model1_InstanceData.rtdw.OUTPUT_1_0_Simulator, &fmuInternalState->ssStateSize[1]);
    }
    if (multibody_model_DW.Model3_InstanceData.rtdw.STATE_1_Simulator) {
        fmuInternalState->ssOp[2] = nesl_save_simdata(multibody_model_DW.Model3_InstanceData.rtdw.STATE_1_Simulator, &fmuInternalState->ssStateSize[2]);
    }
    if (multibody_model_DW.Model3_InstanceData.rtdw.OUTPUT_1_1_Simulator) {
        fmuInternalState->ssOp[3] = nesl_save_simdata(multibody_model_DW.Model3_InstanceData.rtdw.OUTPUT_1_1_Simulator, &fmuInternalState->ssStateSize[3]);
    }
    if (multibody_model_DW.Model3_InstanceData.rtdw.STATE_1_Simulator_o) {
        fmuInternalState->ssOp[4] = nesl_save_simdata(multibody_model_DW.Model3_InstanceData.rtdw.STATE_1_Simulator_o, &fmuInternalState->ssStateSize[4]);
    }
    if (multibody_model_DW.Model3_InstanceData.rtdw.OUTPUT_1_0_Simulator) {
        fmuInternalState->ssOp[5] = nesl_save_simdata(multibody_model_DW.Model3_InstanceData.rtdw.OUTPUT_1_0_Simulator, &fmuInternalState->ssStateSize[5]);
    }
    if (multibody_model_DW.Model3_InstanceData.rtdw.OUTPUT_1_0_Simulator_l) {
        fmuInternalState->ssOp[6] = nesl_save_simdata(multibody_model_DW.Model3_InstanceData.rtdw.OUTPUT_1_0_Simulator_l, &fmuInternalState->ssStateSize[6]);
    }
    if (multibody_model_DW.Model3_InstanceData.rtdw.STATE_1_Simulator_a) {
        fmuInternalState->ssOp[7] = nesl_save_simdata(multibody_model_DW.Model3_InstanceData.rtdw.STATE_1_Simulator_a, &fmuInternalState->ssStateSize[7]);
    }
    if (multibody_model_DW.Model3_InstanceData.rtdw.OUTPUT_1_0_Simulator_h) {
        fmuInternalState->ssOp[8] = nesl_save_simdata(multibody_model_DW.Model3_InstanceData.rtdw.OUTPUT_1_0_Simulator_h, &fmuInternalState->ssStateSize[8]);
    }
    if (multibody_model_DW.Model4_InstanceData.rtdw.STATE_1_Simulator) {
        fmuInternalState->ssOp[9] = nesl_save_simdata(multibody_model_DW.Model4_InstanceData.rtdw.STATE_1_Simulator, &fmuInternalState->ssStateSize[9]);
    }
    if (multibody_model_DW.Model4_InstanceData.rtdw.OUTPUT_1_0_Simulator) {
        fmuInternalState->ssOp[10] = nesl_save_simdata(multibody_model_DW.Model4_InstanceData.rtdw.OUTPUT_1_0_Simulator, &fmuInternalState->ssStateSize[10]);
    }
    fmuInternalState->time = modelData->time;
    fmuInternalState->isNullInstance = (boolean_T)(_instance==NULL);
    if (modelData->loggingOn && modelData->logMessage && modelData->loggingLevel[0]) {
        char msgBuffer[255];
        snprintf(msgBuffer, 255, "FMUstate saved at time %f.", modelData->time);
        modelData->logMessage(modelData->instanceEnvironment, fmi3OK, "info", msgBuffer);
    }
    *FMUState = (void*)(fmuInternalState);
    return fmi3OK;
}

