fmi3Status fmi3UpdateDiscreteStates(fmi3Instance instance, fmi3Boolean* discreteStatesNeedUpdate, fmi3Boolean* terminateSimulation, fmi3Boolean* nominalsOfContinuousStatesChanged, fmi3Boolean* valuesOfContinuousStatesChanged, fmi3Boolean* nextEventTimeDefined, fmi3Float64* nextEventTime) {
    FMUModelData *modelData = (FMUModelData *)instance;
    _instance = modelData;
    if(modelData->loggingOn && modelData->logMessage)
        modelData->logMessage(modelData->instanceEnvironment,fmi3OK, "info", "UpdateDiscreteStates");

    if (!modelData->eventProcessed) {
        /* call step after setting input variables*/
         rtOneStep(modelData->S);;
        if (rtmGetStopRequested(modelData->S)) {
            if(modelData->loggingOn && modelData->logMessage)
                modelData->logMessage(modelData->instanceEnvironment, fmi3Error, "error", "stop requested in fmi3UpdateDiscreteStates");
            return fmi3Error;
        }
        modelData->eventProcessed = true;
    }

    *discreteStatesNeedUpdate = false;
    *terminateSimulation = false;
    *nominalsOfContinuousStatesChanged = false;
    *valuesOfContinuousStatesChanged = false;
    *nextEventTimeDefined = false;
    *nextEventTime = 0;
    return fmi3OK;
}

